#!/usr/bin/env python3
# Generated by morzsa via A2A Mesh delegation
"""
ACK-vihar mérséklés: node-restart után exponential backoff + jitter a retry-kra.

A Tor restartnál Manon 74 failed ACK gyűlt össze — ez a modul randomizált
ütemezéssel (exponential backoff + full jitter) osztja szét a retry-kat,
hogy elkerülje az ACK-vihart.

Használat:
    python a2a_mesh/ack_backoff.py            # demo / self-test
    python a2a_mesh/ack_backoff.py --replay   # DLQ-visszajátszás szimuláció
"""

from __future__ import annotations

import argparse
import heapq
import logging
import math
import random
import threading
import time
from dataclasses import dataclass, field
from enum import Enum
from typing import Callable, Dict, List, Optional, Tuple

logger = logging.getLogger("a2a_mesh.ack_backoff")

# ---------------------------------------------------------------------------
# Konstansok
# ---------------------------------------------------------------------------

DEFAULT_BASE_DELAY_MS = 500          # kezdő késleltetés
DEFAULT_MAX_DELAY_MS = 30_000        # felső korlát (30 s)
DEFAULT_MAX_RETRIES = 8              # max próbálkozás / ACK
DEFAULT_JITTER = "full"              # "full" | "equal" | "decorrelated"
DEFAULT_BATCH_SPREAD_MS = 2000       # restart után ACK-k szétosztásának ablaka
DEFAULT_CONCURRENCY = 16             # párhuzamos retry-k száma


# ---------------------------------------------------------------------------
# Adatstruktúrák
# ---------------------------------------------------------------------------

class JitterStrategy(str, Enum):
    FULL = "full"
    EQUAL = "equal"
    DECORRELATED = "decorrelated"


@dataclass(order=True)
class ScheduledRetry:
    """Heap-elem: a következő futtatandó retry."""
    fire_at: float                       # epoch seconds (monotonic offset)
    seq: int                             # tie-breaker a heap-ben
    ack_id: str = field(compare=False)
    attempt: int = field(compare=False)
    target_node: str = field(compare=False)
    payload: dict = field(compare=False, default_factory=dict)


@dataclass
class AckRecord:
    """Egyetlen ACK állapota."""
    ack_id: str
    target_node: str
    payload: dict
    attempt: int = 0
    last_delay_ms: float = 0.0
    last_error: Optional[str] = None
    delivered: bool = False
    dead_lettered: bool = False


# ---------------------------------------------------------------------------
# Backoff kalkulátor
# ---------------------------------------------------------------------------

class BackoffCalculator:
    """
    Exponential backoff + jitter.

    Stratégiák (AWS architecture blog alapján):
      - full:         delay = random(0, min(base * 2^attempt, cap))
      - equal:        delay = base * 2^attempt + random(0, base)
      - decorrelated: delay = min(cap, random(base, prev_delay * 3))
    """

    def __init__(
        self,
        base_ms: float = DEFAULT_BASE_DELAY_MS,
        cap_ms: float = DEFAULT_MAX_DELAY_MS,
        strategy: JitterStrategy = JitterStrategy.FULL,
        rng: Optional[random.Random] = None,
    ) -> None:
        self.base = base_ms
        self.cap = cap_ms
        self.strategy = strategy
        self.rng = rng or random.Random()

    def delay_ms(self, attempt: int, prev_delay_ms: float = 0.0) -> float:
        exp = min(self.cap, self.base * (2 ** attempt))
        if self.strategy == JitterStrategy.FULL:
            return self.rng.uniform(0, exp)
        elif self.strategy == JitterStrategy.EQUAL:
            return exp + self.rng.uniform(0, self.base)
        elif self.strategy == JitterStrategy.DECORRELATED:
            return min(self.cap, self.rng.uniform(self.base, max(self.base, prev_delay_ms * 3)))
        else:
            raise ValueError(f"Unknown jitter strategy: {self.strategy}")


# ---------------------------------------------------------------------------
# Retry scheduler
# ---------------------------------------------------------------------------

class AckRetryScheduler:
    """
    Központi retry-ütemező.

    Funkciók:
      - ACK-k regisztrálása (új vagy restart után újraküldendő)
      - Exponential backoff + jitter alapú késleltetés
      - Restart után ACK-k szétosztása egy spread-ablakon belül
      - Párhuzamos feldolgozás korlátozott konkurenciával
      - DLQ (dead-letter queue) kezelés max retry után
    """

    def __init__(
        self,
        send_fn: Callable[[str, str, dict], Tuple[bool, Optional[str]]],
        base_ms: float = DEFAULT_BASE_DELAY_MS,
        cap_ms: float = DEFAULT_MAX_DELAY_MS,
        max_retries: int = DEFAULT_MAX_RETRIES,
        jitter: JitterStrategy = JitterStrategy.FULL,
        batch_spread_ms: float = DEFAULT_BATCH_SPREAD_MS,
        concurrency: int = DEFAULT_CONCURRENCY,
        rng_seed: Optional[int] = None,
    ) -> None:
        self.send_fn = send_fn
        self.max_retries = max_retries
        self.batch_spread_ms = batch_spread_ms
        self.concurrency = concurrency
        self.calc = BackoffCalculator(base_ms, cap_ms, jitter,
                                      rng=random.Random(rng_seed) if rng_seed else random.Random())

        self._heap: List[ScheduledRetry] = []
        self._seq = 0
        self._records: Dict[str, AckRecord] = {}
        self._dlq: List[AckRecord] = []
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._worker: Optional[threading.Thread] = None
        self._semaphore = threading.Semaphore(concurrency)

    # -- publikus API -------------------------------------------------------

    def register_ack(self, ack_id: str, target_node: str, payload: dict) -> None:
        """Új ACK regisztrálása azonnali küldésre."""
        with self._lock:
            self._records[ack_id] = AckRecord(ack_id=ack_id, target_node=target_node, payload=payload)
            self._enqueue(ack_id, attempt=0, delay_ms=0.0)

    def register_batch_after_restart(
        self, acks: List[Tuple[str, str, dict]], spread_ms: Optional[float] = None
    ) -> int:
        """
        Node-restart után több (pl. 74) failed ACK újraküldése.

        Az ACK-kat egy spread-ablakon (alapértelmezett batch_spread_ms)
        belül véletlenszerűen osztja szét, HOGY ne küldje mind egyszerre.
        Ezen felül minden retry exponential backoff + jitter-t kap.

        Visszatér a regisztrált ACK-k számával.
        """
        spread = spread_ms if spread_ms is not None else self.batch_spread_ms
        now = time.monotonic()
        count = 0
        with self._lock:
            for ack_id, target_node, payload in acks:
                # Kezdeti szétosztás a spread-ablakon belül (jitter a vihar elkerülésére)
                initial_offset_s = self.calc.rng.uniform(0, spread / 1000.0)
                self._records[ack_id] = AckRecord(
                    ack_id=ack_id, target_node=target_node, payload=payload
                )
                self._seq += 1
                heapq.heappush(
                    self._heap,
                    ScheduledRetry(
                        fire_at=now + initial_offset_s,
                        seq=self._seq,
                        ack_id=ack_id,
                        attempt=0,
                        target_node=target_node,
                        payload=payload,
                    ),
                )
                count += 1
        logger.info("Registered %d ACKs after restart, spread over %.0f ms", count, spread)
        return count

    def start(self) -> None:
        """Worker thread indítása."""
        if self._worker and self._worker.is_alive():
            return
        self._stop.clear()
        self._worker = threading.Thread(target=self._run, name="ack-retry-scheduler", daemon=True)
        self._worker.start()

    def stop(self, timeout: float = 5.0) -> None:
        """Worker thread leállítása."""
        self._stop.set()
        if self._worker:
            self._worker.join(timeout=timeout)

    def stats(self) -> dict:
        with self._lock:
            total = len(self._records)
            delivered = sum(1 for r in self._records.values() if r.delivered)
            dead = len(self._dlq)
            pending = total - delivered - dead
            return {
                "total": total,
                "delivered": delivered,
                "pending": pending,
                "dead_lettered": dead,
                "heap_size": len(self._heap),
            }

    def dead_letters(self) -> List[dict]:
        with self._lock:
            return [
                {
                    "ack_id": r.ack_id,
                    "target_node": r.target_node,
                    "attempts": r.attempt,
                    "last_error": r.last_error,
                }
                for r in self._dlq
            ]

    # -- belső ---------------------------------------------------------------

    def _enqueue(self, ack_id: str, attempt: int, delay_ms: float) -> None:
        now = time.monotonic()
        rec = self._records.get(ack_id)
        if rec is None:
            return
        rec.attempt = attempt
        rec.last_delay_ms = delay_ms
        self._seq += 1
        heapq.heappush(
            self._heap,
            ScheduledRetry(
                fire_at=now + delay_ms / 1000.0,
                seq=self._seq,
                ack_id=ack_id,
                attempt=attempt,
                target_node=rec.target_node,
                payload=rec.payload,
            ),
        )

    def _run(self) -> None:
        while not self._stop.is_set():
            with self._lock:
                if not self._heap:
                    next_wake = 0.5
                else:
                    top = self._heap[0]
                    next_wake = max(0.0, top.fire_at - time.monotonic())
            if next_wake > 0:
                if self._stop.wait(timeout=min(next_wake, 1.0)):
                    break

            with self._lock:
                if not self._heap:
                    continue
                top = self._heap[0]
                if top.fire_at > time.monotonic():
                    continue
                heapq.heappop(self._heap)
                ack_id = top.ack_id
                attempt = top.attempt
                rec = self._records.get(ack_id)
                if rec is None or rec.delivered or rec.dead_lettered:
                    continue

            # Küldés konkurencia-korláttal
            self._semaphore.acquire()
            t = threading.Thread(
                target=self._send_and_reschedule,
                args=(ack_id, attempt),
                daemon=True,
            )
            t.start()

    def _send_and_reschedule(self, ack_id: str, attempt: int) -> None:
        try:
            rec = self._records.get(ack_id)
            if rec is None:
                return
            ok, err = self.send_fn(rec.target_node, ack_id, rec.payload)

            with self._lock:
                rec = self._records.get(ack_id)
                if rec is None:
                    return
                if ok:
                    rec.delivered = True
                    logger.debug("ACK %s delivered on attempt %d", ack_id, attempt)
                    return
                rec.last_error = err
                next_attempt = attempt + 1
                if next_attempt > self.max_retries:
                    rec.dead_lettered = True
                    self._dlq.append(rec)
                    logger.warning(
                        "ACK %s dead-lettered after %d attempts: %s",
                        ack_id, next_attempt, err,
                    )
                    return
                delay = self.calc.delay_ms(next_attempt, rec.last_delay_ms)
                self._enqueue(ack_id, next_attempt, delay)
                logger.debug(
                    "ACK %s retry %d scheduled in %.0f ms (err=%s)",
                    ack_id, next_attempt, delay, err,
                )
        finally:
            self._semaphore.release()


# ---------------------------------------------------------------------------
# Demo / self-test
# ---------------------------------------------------------------------------

def _make_flaky_send(fail_rate: float, rng: random.Random):
    """Szimulált küldő függvény: fail_rate valószínűséggel elbukik."""
    def send(target_node: str, ack_id: str, payload: dict) -> Tuple[bool, Optional[str]]:
        if rng.random() < fail_rate:
            return False, f"connection_refused@{target_node}"
        return True, None
    return send


def _demo():
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
        datefmt="%H:%M:%S",
    )

    rng = random.Random(42)

    # Szimulált Tor-restart: 74 failed ACK gyűlt össze
    failed_acks = [
        (f"ack-{i:03d}", "manon-tor-node", {"seq": i, "ts": time.time()})
        for i in range(74)
    ]

    # Flaky sender: első próbálkozásokra 80% hiba (Tor még indul)
    send_fn = _make_flaky_send(fail_rate=0.8, rng=rng)

    scheduler = AckRetryScheduler(
        send_fn=send_fn,
        base_ms=500,
        cap_ms=15_000,
        max_retries=8,
        jitter=JitterStrategy.FULL,
        batch_spread_ms=3000,   # 74 ACK-t 3 s alatt osztjuk szét
        concurrency=8,
        rng_seed=42,
    )

    print("=" * 70)
    print("ACK-vihar mérséklés — exponential backoff + jitter demo")
    print(f"  74 failed ACK regisztrálása Tor-restart után")
    print(f"  batch_spread=3000ms, base=500ms, cap=15000ms, jitter=full")
    print("=" * 70)

    scheduler.register_batch_after_restart(failed_acks, spread_ms=3000)
    scheduler.start()

    # Várakozás és statisztika minden másodpercben
    start = time.monotonic()
    while time.monotonic() - start < 30:
        time.sleep(1)
        s = scheduler.stats()
        elapsed = time.monotonic() - start
        print(f"  [{elapsed:5.1f}s] delivered={s['delivered']:3d}  "
              f"pending={s['pending']:3d}  dead={s['dead_lettered']:3d}  "
              f"heap={s['heap_size']:3d}")
        if s["pending"] == 0 and s["heap_size"] == 0:
            break

    scheduler.stop(timeout=3)
    s = scheduler.stats()
    print("=" * 70)
    print(f"  VÉGEREDMÉNY: delivered={s['delivered']}  dead_lettered={s['dead_lettered']}")
    dl = scheduler.dead_letters()
    if dl:
        print(f"  DLQ ({len(dl)} elem):")
        for d in dl[:5]:
            print(f"    {d['ack_id']} -> {d['target_node']} "
                  f"(attempts={d['attempts']}, err={d['last_error']})")
        if len(dl) > 5:
            print(f"    ... és még {len(dl) - 5}")
    print("=" * 70)
    print("OK — ACK-vihar elkerülve: a retry-k szétosztva, nem egyszerre.")


def _replay_sim():
    """DLQ-visszajátszás szimuláció: canary előtt."""
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
        datefmt="%H:%M:%S",
    )
    rng = random.Random(99)
    send_fn = _make_flaky_send(fail_rate=0.3, rng=rng)
    scheduler = AckRetryScheduler(
        send_fn=send_fn,
        base_ms=200,
        cap_ms=10_000,
        max_retries=5,
        jitter=JitterStrategy.DECORRELATED,
        batch_spread_ms=1000,
        concurrency=4,
        rng_seed=99,
    )
    acks = [(f"dlq-{i:03d}", "replay-node", {"origin": "dlq", "idx": i}) for i in range(20)]
    scheduler.register_batch_after_restart(acks, spread_ms=1000)
    scheduler.start()
    start = time.monotonic()
    while time.monotonic() - start < 20:
        time.sleep(1)
        s = scheduler.stats()
        print(f"  [{time.monotonic()-start:4.1f}s] delivered={s['delivered']:2d} "
              f"pending={s['pending']:2d} dead={s['dead_lettered']:2d}")
        if s["pending"] == 0:
            break
    scheduler.stop(timeout=3)
    print(f"Replay done: {scheduler.stats()}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="ACK backoff + jitter scheduler")
    parser.add_argument("--replay", action="store_true", help="DLQ replay simulation")
    args = parser.parse_args()
    if args.replay:
        _replay_sim()
    else:
        _demo()